using System;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>One four-sided facade piece cut from a surface; travels on its own "Panel" wire.</summary>
    public class Panel : IBettaValue
    {
        public Panel() : this(Point3d.Origin, Point3d.Origin, Point3d.Origin, Point3d.Origin, 0) { }

        public Panel(Point3d a, Point3d b, Point3d c, Point3d d, int index)
        {
            Corners = new[] { a, b, c, d };
            Index = index;
        }

        /// <summary>The four corners in order around the panel.</summary>
        public Point3d[] Corners { get; }

        /// <summary>Index in the grid.</summary>
        public int Index { get; }

        public Curve Outline => new PolylineCurve(new[] { Corners[0], Corners[1], Corners[2], Corners[3], Corners[0] });

        public Point3d Center => (Corners[0] + Corners[1] + Corners[2] + Corners[3]) / 4.0;

        /// <summary>Area as two triangles split along the diagonal (half the cross product of the diagonals).</summary>
        public double Area => 0.5 * Vector3d.CrossProduct(Corners[2] - Corners[0], Corners[3] - Corners[1]).Length;

        /// <summary>Distance from the fourth corner to the plane through the other three.</summary>
        public double Deviation
        {
            get
            {
                var plane = new Plane(Corners[0], Corners[1], Corners[2]);
                return plane.IsValid ? Math.Abs(plane.DistanceTo(Corners[3])) : 0.0;
            }
        }

        public double Edge(int i) => Corners[i].DistanceTo(Corners[(i + 1) % 4]);

        /// <summary>Mean of the first and third edge lengths.</summary>
        public double Width => (Edge(0) + Edge(2)) / 2.0;

        /// <summary>Mean of the second and fourth edge lengths.</summary>
        public double Height => (Edge(1) + Edge(3)) / 2.0;
    }
}

