using System;
using System.Collections.Generic;
using System.Linq;
using Betta.Attributes;
using Betta.Interfaces;

namespace BenchPlugin.Facade
{
    [GrasshopperCollection("Facade", "Analysis")]
    public interface IAnalysisComponents : IBettaCollection
    {
        [GrasshopperMethod("Planarity", "Planarity deviation of each panel and whether it is within tolerance")]
        (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 0.5)] double tolerance,
            IBettaReport report);

        [GrasshopperMethod("Classify Panels", "Classify panels as flat, cold-bent or custom")]
        (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 0.5)] double tolerance);

        [GrasshopperMethod("Panel Stats", "Total, minimum, maximum and mean panel area")]
        (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(
            [GrasshopperParameter("Panels")] List<Panel> panels);
    }

    public class AnalysisComponents : IAnalysisComponents
    {
        public (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            List<Panel> panels, double tolerance, IBettaReport report)
        {
            var deviation = (panels ?? new List<Panel>()).Select(p => p.Deviation).ToList();
            var flat = deviation.Select(d => d <= tolerance).ToList();
            int flatCount = flat.Count(f => f);
            int notFlat = flat.Count - flatCount;
            if (notFlat * 2 > flat.Count)
                report.Warning($"{notFlat} of {flat.Count} panels are not flat.");
            return (deviation, flat, flatCount);
        }

        public (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            List<Panel> panels, double tolerance)
        {
            var types = new List<string>();
            int flat = 0, coldBent = 0, custom = 0;
            foreach (var panel in panels ?? new List<Panel>())
            {
                double d = panel.Deviation;
                if (d <= tolerance) { types.Add("flat"); flat++; }
                else if (d <= 10 * tolerance) { types.Add("cold-bent"); coldBent++; }
                else { types.Add("custom"); custom++; }
            }
            return (types, flat, coldBent, custom);
        }

        public (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(List<Panel> panels)
        {
            if (panels == null || panels.Count == 0) throw new ArgumentException("There are no panels.");
            var areas = panels.Select(p => p.Area).ToList();
            double total = areas.Sum();
            return (total, areas.Min(), areas.Max(), total / areas.Count);
        }
    }
}

